const $=s=>document.querySelector(s),arr=v=>Array.isArray(v)?v:[],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),human=v=>String(v??'unreported').replaceAll('_',' '),finite=v=>typeof v==='number'&&Number.isFinite(v),num=(v,d=0)=>finite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'Unknown',unique=a=>[...new Set(a)],text=v=>typeof v==='string'?v:Array.isArray(v)?v.map(text).join('; '):v&&typeof v==='object'?Object.entries(v).map(([k,x])=>human(k)+': '+text(x)).join('; '):String(v??''),safeUrl=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}};
const state={registers:[],sources:[],mediums:[],entities:[],claims:[],groups:[],leads:[],analysis:null,coverage:null,analysisError:null,coverageError:null,query:'',kind:'all',tradition:'all',repeated:false,page:1,groupMode:'all',graphGroup:'',sourceQuery:'',sourceDepth:'all',sourcePage:1};
const views=['register','connections','repeated','analysis','coverage','methods'];
const medium=id=>state.mediums.find(m=>m.id===id),entity=id=>state.entities.find(e=>e.id===id),source=id=>state.sources.find(s=>s.id===id),name=x=>x?.name||x?.label||x?.title||x?.id||'Unreported',claimsFor=(type,id)=>state.claims.filter(c=>type==='medium'?c.medium_id===id:c.channellee_id===id),isHuman=m=>['medium','channeler','joint_practice_medium'].includes(m?.role),kind=e=>e?.kind||'unreported';
const link=(url,label)=>safeUrl(url)?`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label),recordButton=(type,id,label,cl='text-button')=>`<button class="${cl}" type="button" data-inspect="${esc(type)}" data-id="${esc(id)}">${esc(label)}</button>`,head=(eyebrow,title,lede)=>`<header class="page-head"><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p>${esc(lede)}</p></header>`,badge=(k)=>`<span class="badge ${/civilization|collective|group/i.test(k)?'collective':/person|being|angel|deity|named|entity/i.test(k)?'named':'unknown'}">${esc(human(k))}</span>`,announce=s=>{$('#live-status').textContent=s;};
function mergeById(rows){const map=new Map();for(const r of rows){if(!r?.id)throw Error('A register record is missing its identifier.');const old=map.get(r.id);if(!old){map.set(r.id,{...r});continue;}for(const key of ['name','label','kind','role','tradition','medium_id','channellee_id'])if(old[key]!=null&&r[key]!=null&&JSON.stringify(old[key])!==JSON.stringify(r[key]))throw Error('Conflicting identity '+r.id+' field '+key);map.set(r.id,{...old,...r,source_ids:unique([...arr(old.source_ids),...arr(r.source_ids)]),accounts:[...arr(old.accounts),...arr(r.accounts)].filter((a,i,all)=>all.findIndex(b=>(b.url||b)===(a.url||a))===i)});}return [...map.values()];}
function normalize(){state.sources=mergeById(state.registers.flatMap(r=>arr(r.sources)));state.mediums=mergeById(state.registers.flatMap(r=>arr(r.mediums)));state.entities=mergeById(state.registers.flatMap(r=>arr(r.channellees)));state.claims=mergeById(state.registers.flatMap(r=>arr(r.claims)));state.groups=mergeById(state.registers.flatMap(r=>arr(r.comparison_groups)));state.leads=state.registers.flatMap(r=>arr(r.leads));for(const c of state.claims){if(!medium(c.medium_id)||!entity(c.channellee_id))throw Error('A claim points to a missing medium or claimed identity.');}for(const e of state.entities){if(!state.groups.some(g=>arr(g.channellee_ids).includes(e.id)))state.groups.push({id:'entity:'+e.id,label:name(e),kind:kind(e),identity_equivalence:false,channellee_ids:[e.id],medium_ids:unique(claimsFor('entity',e.id).map(c=>c.medium_id)),notes:'This row retains a claimed-name record; no cross-source equivalence is established.'});}for(const e of state.entities){if(e.comparison_group_id){const target=state.groups.find(g=>g.id===e.comparison_group_id);if(!target)throw Error('Missing declared comparison group '+e.comparison_group_id);target.channellee_ids=unique([...arr(target.channellee_ids),e.id]);}}state.groups.sort((a,b)=>groupMediums(b).length-groupMediums(a).length||name(a).localeCompare(name(b)));}
function groupClaims(g){return state.claims.filter(c=>arr(g?.channellee_ids).includes(c.channellee_id));}
const directRelations=new Set(['claims_to_channel','channels_named_entity','channels_collective']);
function groupMediums(g,directOnly=false){return unique(groupClaims(g).filter(c=>!directOnly||directRelations.has(c.relation)).map(c=>c.medium_id)).map(medium).filter(isHuman).filter(Boolean);}
