function sourcesBlock(ids){const rows=unique(ids).map(source).filter(Boolean);return rows.length?`<ul class="source-list">${rows.map(s=>`<li>${link(s.url,name(s))}<small><strong>${esc(human(s.access_depth||s.access||'access depth unreported'))}</strong> · ${esc(human(s.content_kind||s.source_type||'content kind unreported'))} · checked ${esc(s.checked_at||'date unreported')}</small>${s.note?`<p>${esc(text(s.note))}</p>`:''}</li>`).join('')}</ul>`:'<p class="empty">No resolved evidence source is linked to this record.</p>';}
function facts(rows){return `<dl class="record-meta">${rows.filter(r=>r[1]!==undefined&&r[1]!==null&&r[1]!=='').map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(text(v))}</dd>`).join('')}</dl>`;}
function register(){return head('RESEARCHED CLAIMS · SOURCE-SPECIFIC IDENTITIES','Who speaks for whom?','Explore human mediums, publishing accounts and the beings or collectives they claim to channel. Follow each relationship back to its evidence.')+`<div class="scope-note"><p><strong>Names are a research index, not an identity test.</strong> “Ra,” “Pleiadian,” “Michael” or “Christ” can refer to different source-specific claims. A shared label does not establish the same being, teaching, culture or historical origin.</p></div><div class="metrics"><div><b>${num(state.mediums.filter(isHuman).length)}</b><span>researched human-medium records</span></div><div><b>${num(state.entities.length)}</b><span>claimed-name records</span></div><div><b>${num(state.claims.length)}</b><span>documented attribution links</span></div><div><b>${num(state.sources.length)}</b><span>source-ledger records, including blocked leads</span></div></div><form class="toolbar" id="register-filters"><label class="search">Search medium, claimed name or tradition<input id="register-query" type="search" value="${esc(state.query)}" placeholder="e.g. Erik, Kryon, Pleiadian"></label><label>Claimed identity type<select id="register-kind"><option value="all">All types</option>${unique(state.entities.map(kind)).sort().map(k=>`<option value="${esc(k)}" ${k===state.kind?'selected':''}>${esc(human(k))}</option>`).join('')}</select></label><label>Attributed tradition<select id="register-tradition"><option value="all">All traditions</option>${unique(state.entities.map(e=>text(e.tradition)).filter(Boolean)).sort().map(t=>`<option value="${esc(t)}" ${t===state.tradition?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="check"><input id="register-repeated" type="checkbox" ${state.repeated?'checked':''}>Shared-label group with 2+ mediums</label><button id="clear-register" class="secondary" type="button">Clear filters</button></form><div id="register-results">${registerResults()}</div>`;}
function filteredClaims(){const q=state.query.trim().toLowerCase();return state.claims.filter(c=>{const m=medium(c.medium_id),e=entity(c.channellee_id),g=state.groups.filter(g=>arr(g.channellee_ids).includes(e.id));return (state.kind==='all'||kind(e)===state.kind)&&(state.tradition==='all'||text(e.tradition)===state.tradition)&&(!state.repeated||g.some(g=>groupMediums(g).length>=2))&&(!q||[name(m),m.id,name(e),e.id,text(e.aliases),text(e.tradition),text(m.accounts),...g.map(name)].join(' ').toLowerCase().includes(q));});}
