function registerResults(){const rows=filteredClaims(),size=16;state.page=Math.min(state.page,Math.max(1,Math.ceil(rows.length/size)));return `<div class="result-summary"><p><strong>${num(rows.length)}</strong> attribution links match. A row is a claimed relationship, not a recording or an independent experimental observation.</p><button type="button" class="secondary" id="export-register">Export filtered links (CSV)</button></div><div class="table-wrap" tabindex="0" role="region" aria-label="Claimed relationships table"><table class="register-table"><thead><tr><th>Human medium</th><th>Claimed channellee</th><th>Type / tradition</th><th>Evidence scope</th></tr></thead><tbody>${rows.slice((state.page-1)*size,state.page*size).map(c=>{const m=medium(c.medium_id),e=entity(c.channellee_id);return `<tr><th scope="row">${recordButton('medium',m.id,name(m),'text-button record-label')}<small>${arr(m.accounts).length} listed publishing account(s) · ${esc(human(m.role||'medium'))}</small></th><td>${recordButton('entity',e.id,name(e),'text-button record-label')}<small>${esc(human(c.relation))}</small></td><td>${badge(kind(e))}<small>${esc(text(e.tradition)||'Tradition not assigned')}</small></td><td>${recordButton('claim',c.id,'Inspect attribution')}<small>${num(unique(arr(c.source_ids)).length)} source(s) · ${esc(text(c.scope)||'scope unreported')}</small></td></tr>`;}).join('')||'<tr><td colspan="4"><p class="empty">No claimed relationships match these filters. Clear the search or choose a wider type.</p></td></tr>'}</tbody></table></div>${pager('register',state.page,rows.length)}${unlinkedPeople(rows)}`;}
