function connections(){if(!state.groups.some(g=>g.id===state.graphGroup))state.graphGroup=state.groups[0]?.id||'';return head('CLAIM NETWORK · NOT A SIMILARITY MODEL','Follow a claimed connection.','Choose a label neighborhood, then inspect the people, claimed-name records and the sources linking them.')+`<form class="toolbar" id="graph-filters"><label>Claimed label neighborhood<select id="graph-group">${groupOptions()}</select></label><button class="secondary" id="export-graph" type="button">Export neighborhood links</button></form><p class="caption">The graph scrolls horizontally on small screens. <a href="#repeated">Open the full-size table alternative →</a></p><div id="graph-results">${graphResults()}</div>`;}
function graphResults(){const g=state.groups.find(x=>x.id===state.graphGroup);if(!g)return '<p class="empty">No attributed relationships are available in the source registers.</p>';const cs=groupClaims(g),ms=unique(cs.map(c=>c.medium_id)).map(medium).filter(Boolean),es=arr(g.channellee_ids).map(entity).filter(Boolean),h=Math.max(360,Math.max(ms.length,es.length)*72+80),nodes=[...ms.map((m,i)=>({r:m,type:'medium',x:180,y:60+(i+.5)*(h-100)/Math.max(1,ms.length)})),...es.map((e,i)=>({r:e,type:'entity',x:650,y:60+(i+.5)*(h-100)/Math.max(1,es.length)}))],pos=id=>nodes.find(n=>n.r.id===id),wrapLabel=s=>{const words=String(s).split(' '),lines=[''];for(const w of words){if((lines[lines.length-1]+' '+w).length>25&&lines[lines.length-1])lines.push(w);else lines[lines.length-1]+=(lines[lines.length-1]?' ':'')+w;}return lines;};return `<div class="section-head"><h2>${esc(name(g))}</h2><p>${esc(text(g.notes||g.note)||'Relationships are attributed to the linked source records.')} Direct channeling attributions: <strong>${num(groupMediums(g,true).length)}</strong> medium records; all relationship types: ${num(groupMediums(g).length)}.</p></div><div class="graph-layout"><div class="graph-frame"><div class="graph-scroll" tabindex="0" role="region" aria-label="Horizontally scrollable relationship graph"><svg viewBox="0 0 830 ${h}" role="group" aria-label="${esc(name(g))} attributed relationship graph"><title>${esc(name(g))}: humans on the left, claimed-name records on the right</title><text x="180" y="27" text-anchor="middle" fill="#56645d" font-size="12">HUMAN MEDIUM / HOST</text><text x="650" y="27" text-anchor="middle" fill="#56645d" font-size="12">CLAIMED IDENTITY</text>${cs.map(c=>{const a=pos(c.medium_id),b=pos(c.channellee_id);return a&&b?`<path class="graph-edge ${directRelations.has(c.relation)?'direct':'indirect'}" d="M${a.x+13},${a.y} C420,${a.y} 420,${b.y} ${b.x-13},${b.y}"/>`:'';}).join('')}${nodes.map(n=>`<g class="graph-node" role="button" tabindex="0" data-inspect="${n.type}" data-id="${esc(n.r.id)}" aria-label="Inspect ${n.type==='medium'?'human':'claimed identity'} ${esc(name(n.r))}"><circle cx="${n.x}" cy="${n.y}" r="18" fill="${n.type==='medium'?'#345743':'#91512f'}"/><text x="${n.x}" y="${n.y+29}" text-anchor="middle">${wrapLabel(name(n.r)).map((l,i)=>`<tspan x="${n.x}" dy="${i?14:0}">${esc(l)}</tspan>`).join('')}</text></g>`).join('')}</svg></div><p>Lines mean “a cited source attributes this claim.” Position is a two-column layout; distance and line length encode no statistical similarity. Every node opens its evidence record.</p></div><aside class="graph-legend"><h3>Read the relationship</h3><div><div class="node-key"><span aria-hidden="true"></span>Human medium / host</div><div class="node-key entity"><span aria-hidden="true"></span>Claimed-name record</div><p><span class="edge-key" aria-hidden="true"></span>Direct channeling attribution<br><span class="edge-key indirect" aria-hidden="true"></span>Directory, category, contact or other relation</p><p>${num(cs.length)} attribution links; ${num(es.length)} retained identity records. Hosts remain separately labeled in their inspector.</p></div><div><p><strong>Identity equivalence: not established.</strong> A comparison group can combine name matches or a broad civilization label while preserving the original records.</p><ul><li>Use Tab and Enter to inspect nodes.</li><li>Publishing accounts are listed under each human, with roles and verification.</li><li>The shared-label matrix provides the same relationships as a table.</li></ul><p><a href="#repeated">Open table alternative →</a></p></div></aside></div><section class="section"><h2>Attribution evidence</h2>${sourcesBlock(cs.flatMap(c=>arr(c.source_ids)))}</section>`;}
function repeated(){return head('COMPARISON MATRIX · IDENTITY RESOLUTION','Shared names, separate claims.','Find repeated named figures and broad collective labels without collapsing their claimed-name records.')+`<div class="scope-note"><p><strong>The count is distinct human-medium records in this register.</strong> Joint practices, reposting, shared publishing accounts and historical hosts can still create dependencies. These are candidates for comparison, not proof of independent origins.</p></div><form class="toolbar" id="matrix-filters"><label>Comparison scope<select id="matrix-mode"><option value="all" ${state.groupMode==='all'?'selected':''}>All groups with 2+ mediums</option><option value="named" ${state.groupMode==='named'?'selected':''}>Named figure / specific collective</option><option value="broad" ${state.groupMode==='broad'?'selected':''}>Broad civilization / tradition labels</option></select></label><button type="button" class="secondary" id="export-matrix">Export comparison matrix</button></form><div id="matrix-results">${matrixResults()}</div>`;}
function matrixGroups(){return state.groups.filter(g=>groupMediums(g).length>=2&&(state.groupMode==='all'||(state.groupMode==='broad'?broad(g):!broad(g))));}
function matrixResults(){const gs=matrixGroups();return `<div class="result-summary"><p><strong>${num(gs.length)}</strong> comparison groups match. The named / broad distinction follows the researcher’s declared grouping, not automatic spelling similarity.</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Shared claimed label matrix"><table class="matrix"><thead><tr><th>Comparison label</th><th>Human-medium records by evidence</th><th>Claimed-name records / evidence</th><th>Separate new-message pilot</th></tr></thead><tbody>${gs.map(g=>`<tr><th scope="row">${recordButton('group',g.id,name(g),'text-button record-label')}<small>${badge(g.kind||'comparison group')}</small></th><td><span class="count">${num(groupMediums(g,true).length)}</span> direct channeling attributions<small>${num(groupMediums(g).length)} linked medium records across all evidence types; directory/category/repost links require separate confirmation.</small><div class="medium-links">${groupMediums(g).map(m=>recordButton('medium',m.id,name(m))).join('')}</div></td><td>${arr(g.channellee_ids).map(entity).filter(Boolean).map(e=>recordButton('entity',e.id,name(e))).join('<br>')}<small>${esc(text(g.notes||g.note)||'No same-entity equivalence has been established.')}</small></td><td>${groupPilotCoverage(g)}</td></tr>`).join('')||'<tr><td colspan="4"><p class="empty">No supported repeated-medium group matches this scope in the current register.</p></td></tr>'}</tbody></table></div>`;}
function metricTable(s){const ids=arr(s.groups),lookup=id=>arr(state.analysis?.coverage?.groups).find(g=>g.id===(typeof id==='object'?id.id:id)),matrix=arr(s.matrix),window=arr(s.window_matrix);if(!ids.length||!matrix.length)return '<p class="empty">No cross-context similarity matrix was released.</p>';return `<div class="table-wrap" tabindex="0" role="region" aria-label="Cross-context similarity table"><table class="matrix"><thead><tr><th>Source context</th>${ids.map(id=>`<th>${esc(name(lookup(id))||text(id))}</th>`).join('')}</tr></thead><tbody>${ids.map((id,i)=>`<tr><th scope="row">${esc(name(lookup(id))||text(id))}</th>${ids.map((_,j)=>`<td>${num(matrix[i]?.[j],4)}<small>window: ${num(window[i]?.[j],4)}<br>${num(s.pair_counts?.[i]?.[j])} document pairs</small></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function figure(f){const file=String(f.file||''),valid=/^[a-zA-Z0-9_./-]+\.(svg|png)$/.test(file)&&!file.includes('..');if(!valid)return '';const path=file.includes('/')?file:'figures/'+file;return `<figure class="figure"><h3>${esc(f.title||human(f.id))}</h3><p class="figure-open"><a href="${esc(path)}" target="_blank" rel="noopener">Open larger figure</a></p><img loading="lazy" src="${esc(path)}${f.sha256?'?v='+esc(f.sha256):''}" alt="${esc(f.alt||f.caption||f.title||'Exploratory text analysis figure')}"><figcaption>${esc(f.caption||f.alt||'See the analysis methods for the fitted source set and limitations.')}<div class="figure-links"><a href="${esc(path)}" download>Download figure</a></div></figcaption></figure>`;}
function analysis(){const a=state.analysis;return head('TEXT ANALYSIS · DISTINCT FROM THE CLAIM GRAPH','Compare the retained language.','Explore source-context topics, lexical similarities, clusters and reading leads. Biographies do not assign a speaker or claimed entity to every passage.')+(!a?`<p class="empty">The expanded text analysis could not be loaded. ${esc(state.analysisError||'No accepted analysis is present.')} The identity registers remain available. <a href="../bashar-ra/">Open the existing Bashar–Ra study</a>.</p>`:`<div class="scope-note"><p>${esc(text(a.scope)||'Analysis uses only the declared retained text units.')} <strong>Source context is not channellee identity.</strong> Similar wording, clusters and embedding scores do not validate a supernatural claim or prove two speakers give equivalent answers.</p></div><div class="metrics"><div><b>${num(a.coverage?.model_documents)}</b><span>deduplicated model documents</span></div><div><b>${num(arr(a.coverage?.groups).length)}</b><span>modeled source contexts</span></div><div><b>${num(arr(a.topics).length)}</b><span>exploratory topic factors</span></div><div><b>${num(arr(a.qa_leads).length)}</b><span>retrieval records · inspect review status</span></div></div><section class="section"><div class="section-head"><h2>Cross-context lexical similarity</h2><p>${esc(text(a.similarities?.metric)||'Declared cosine metric')}. Cells show full text and the declared length-controlled window. These are relative text scores, not agreement probabilities.</p></div>${metricTable(a.similarities||{})}<ul class="limitations">${arr(a.similarities?.limitations).map(l=>`<li>${esc(text(l))}</li>`).join('')}</ul></section><section class="section"><div class="section-head"><h2>Topic factors and clustering</h2><p>Topic words are model outputs. Interpret their supporting passages before naming a belief or assigning a civilization.</p></div><div class="topics">${arr(a.topics).map(t=>`<article class="topic"><h3>${esc(t.label||t.id)}</h3><div class="chips">${arr(t.terms).map(x=>`<span title="${esc(finite(x.weight)?'Factor weight '+num(x.weight,4):'Topic term')}">${esc(typeof x==='string'?x:x.term)}</span>`).join('')}</div><p>${finite(t.documents)?num(t.documents)+' documents with this largest factor weight. ':''}${arr(t.group_weights).map(w=>`${name(arr(a.coverage?.groups).find(g=>g.id===w.group_id))}: ${num(w.weight,3)}`).map(esc).join('; ')}</p></article>`).join('')||'<p class="empty">No topic factors were accepted for this release.</p>'}</div><div class="scope-note"><p><strong>${esc(text(a.clusters?.method)||'Clustering method unreported')}:</strong> k = ${num(a.clusters?.k)}; silhouette = ${num(a.clusters?.silhouette,4)}. A low silhouette indicates overlapping groups. Source format, transcription and document length may explain apparent clusters.</p></div>${arr(a.clusters?.rows).length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Cluster composition"><table><thead><tr><th>Cluster</th><th>Source context</th><th>Model documents</th></tr></thead><tbody>${arr(a.clusters.rows).map(r=>`<tr><th scope="row">${esc(r.cluster)}</th><td>${esc(name(arr(a.coverage?.groups).find(g=>g.id===r.group_id)))}</td><td>${num(r.documents)}</td></tr>`).join('')}</tbody></table></div>`:''}</section><section class="section"><h2>Figures and sensitivity checks</h2>${arr(a.figures).filter(f=>(f.file||'').endsWith('.svg')||(!(arr(a.figures).some(x=>x.id===f.id&&(x.file||'').endsWith('.svg')))&&(f.file||'').endsWith('.png'))).map(figure).join('')}</section><section class="section" id="qa-leads"><div class="section-head"><h2>Question retrieval: examine the mismatches</h2><p>These are source-linked retrieval records, including inspected false matches. The status describes the actual review performed; candidate pairings do not establish matched questions, identified answer turns or equivalent teachings.</p></div>${arr(a.qa_leads).map(q=>`<article class="comparison-row"><h3>${esc(q.question_paraphrase||q.id)}</h3><p><strong>Status:</strong> ${esc(human(q.status))}. Retrieval score: ${num(q.score,4)} (not a probability).</p>${q.comparison?`<p><strong>Reading finding:</strong> ${esc(q.comparison)}</p>`:''}<p><strong>Question context:</strong> ${esc(q.question_context||q.question_source_id)} ${link(q.question_url,'Open question source')}</p><p><strong>Retrieved comparison context:</strong> ${esc(q.response_paraphrase||q.response_context||q.response_source_id)} ${link(q.response_url,'Open response source')}</p><p>${esc(text(q.limitations)||'Speaker and answer boundaries require manual review.')}</p></article>`).join('')||'<p class="empty">No source-linked Q/A comparison has been accepted. Missing answer attribution is a research gap, not evidence of an absent answer.</p>'}</section><section class="section"><h2>Limits on interpretation</h2><ul class="limitations">${arr(a.limitations).map(l=>`<li>${esc(text(l))}</li>`).join('')}</ul></section><div class="downloads"><a href="analysis.json" download>Download aggregate analysis JSON</a><a href="../bashar-ra/#topics">Bashar & Ra topic study</a><a href="../subscription-audit/#publisher-texts">Publisher transcript study</a></div>`);}
function countValue(c,key){const v=c.counts?.[key]??c[key],raw=v&&typeof v==='object'?v.value:v;return finite(raw)?raw:null;}
function coverage(){const d=state.coverage,cs=arr(d?.channels);return head('ACQUISITION ACCOUNTING · DIFFERENT DENOMINATORS','From discovery to analysis.','Keep indexed publications, retained recordings, transcript editions and model units separate. An unknown channel total stays unknown.')+`<div class="scope-note"><p><strong>Current duration rule:</strong> Bashar alone requires at least 300 seconds. Other mediums have no five-minute cutoff and no recording-count cap. Historical five-minute inventory fields retain their original meaning; they are not the current eligibility decision.</p><p>Managed workspace media are not permanent ChatGPT account storage. Public GitHub outputs contain metadata, analysis and build files; retained recordings and full texts are accounted for in private acquisition manifests.</p></div>${!d?`<p class="empty">The account-coverage snapshot could not be loaded. ${esc(state.coverageError||'')} <a href="../subscription-audit/">Open the acquisition audit</a>.</p>`:`<div class="result-summary"><p><strong>${num(cs.length)}</strong> screenshot-account records. This is an account audit, not the full expanded discovery universe. Counts below concern the stated historical/current inventory; publisher audio is a separate source origin.</p><a href="../subscription-audit/">Open detailed per-video audit →</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Account acquisition coverage"><table class="register-table"><thead><tr><th>Publishing account</th><th>Total public uploads</th><th>Indexed videos</th><th>Audio retained</th><th>Video retained</th><th>Transcribed</th><th>Analyzed</th></tr></thead><tbody>${cs.map(c=>`<tr><th scope="row">${esc(c.name||c.handle||c.id)}<small>${esc(c.handle||c.id)} · ${esc(c.status||'unreported')}</small></th><td>${num(countValue(c,'public_uploads_total'))}</td><td>${num(countValue(c,'public_uploads_observed'))}</td><td>${num(countValue(c,'audio_sources_retained'))}</td><td>${num(countValue(c,'video_sources_retained'))}</td><td>${num(countValue(c,'transcribed_sources'))}</td><td>${num(countValue(c,'analyzed_sources'))}</td></tr>`).join('')}</tbody></table></div><p class="caption">“Unknown” does not mean zero. Indexed IDs do not establish a complete, fresh channel census. User-excluded accounts remain in the audit for traceability.</p>`}<section class="section"><h2>Text-model coverage</h2>${state.analysis?`<div class="table-wrap" tabindex="0" role="region" aria-label="Text model source contexts"><table class="register-table"><thead><tr><th>Source context</th><th>Model documents</th><th>Words</th><th>Source role</th><th>Text origin</th></tr></thead><tbody>${arr(state.analysis.coverage?.groups).map(g=>`<tr><th scope="row">${esc(name(g))}</th><td>${num(g.documents)}</td><td>${num(g.words)}</td><td>${esc(human(g.source_role))}</td><td>${esc(human(g.text_origin))}</td></tr>`).join('')}</tbody></table></div><p class="caption">These denominators are model units after declared exclusions and exact-duplicate handling. They must not be summed with publication counts or compared to the account list as though every account were modeled.</p>`:'<p class="empty">Text-model coverage is unavailable.</p>'}<div class="analysis-links"><a href="../bashar-ra/">Retained Bashar / Ra audio and text</a><a href="../subscription-audit/#publisher-texts">Publisher captions and PDF transcripts</a></div></section>`;}
function filteredSources(){const q=state.sourceQuery.toLowerCase();return state.sources.filter(s=>(state.sourceDepth==='all'||(s.access_depth||s.access||'unreported')===state.sourceDepth)&&(!q||[s.id,s.url,name(s),text(s.note)].join(' ').toLowerCase().includes(q)));}
function sourceResults(){const ss=filteredSources(),size=14;state.sourcePage=Math.min(state.sourcePage,Math.max(1,Math.ceil(ss.length/size)));return `<div class="result-summary"><p><strong>${num(ss.length)}</strong> evidence-source records match.</p><button type="button" class="secondary" id="export-sources">Export evidence sources</button></div>${sourcesBlock(ss.slice((state.sourcePage-1)*size,state.sourcePage*size).map(s=>s.id))}${ss.length?'':'<p class="empty">No evidence source matches these filters.</p>'}${pager('sources',state.sourcePage,ss.length,size)}`;}
function methods(){return head('METHODS · SOURCE DEPTH · REMAINING GAPS','Inspect the basis of comparison.','This is an exploratory, source-linked account of channeling claims and retained language. The panel consists of five AI research roles, not independent human experts or peer review.')+`<dl class="method-list"><dt>Separate the levels</dt><dd>A human medium, a host or publisher, an account, a source-specific claimed being, a collective and a tradition have separate records. Accounts can repost or host several people. Account biographies do not label every recording or utterance.</dd><dt>Search, then retain the evidence depth</dt><dd>Researchers use channeling-related names, civilizations, angels, deities and spelling variants to locate public source claims. The source register retains direct pages, publisher descriptions, directory listings and indexed snippets as distinct access depths. Discovery is neither an exhaustive cultural survey nor proof of the reported claim.</dd><dt>Compare source-specific claims</dt><dd>Comparison groups are explicit researcher mappings. Broad labels and named figures remain separable; aliases are not silently merged. Joint practices and hosts are visible. Jamie Butler remains excluded from new acquisition at the user’s request, regardless of research classification.</dd><dt>Analyze only retained texts</dt><dd>TF-IDF, NMF topic factors, clustering, lexical / semantic retrieval and keyword-based extraction use declared source-context units. Models do not infer each passage’s claimed speaker from biographies. Similarity requires a named metric and denominator; no score here is a supernatural truth or agreement probability.</dd><dt>Keep reading and question extraction bounded</dt><dd>Question marks, cue/page boundaries and semantic neighbors yield inspection candidates. Identify questions, answer boundaries, source speakers and context before making a matched-Q/A claim. Machine transcripts, format differences and label leakage can confound apparent overlap.</dd><dt>Acquisition and duration</dt><dd>Only Bashar has a 300-second minimum. Other mediums have no minimum duration. Unavailable source transports and incomplete feed windows are disclosed; publisher RSS, Vimeo, PDFs and captions retain their source origins. Original bytes and compact audio derivatives have distinct lineage.</dd><dt>Local and offline use</dt><dd>This page uses local HTML, CSS, JavaScript and JSON, with no CDN dependency. Serve a downloaded site folder using a local HTTP server; browser restrictions can prevent fetch from file://. Source links and further downloads still require internet access.</dd></dl><section class="section"><h2>Evidence-source index</h2><form class="toolbar" id="source-filters"><label class="search">Search sources<input id="source-query" type="search" value="${esc(state.sourceQuery)}" placeholder="Publisher, URL or source note"></label><label>Access depth<select id="source-depth"><option value="all">All evidence depths</option>${unique(state.sources.map(s=>s.access_depth||s.access||'unreported')).sort().map(k=>`<option value="${esc(k)}" ${k===state.sourceDepth?'selected':''}>${esc(human(k))}</option>`).join('')}</select></label><button type="button" class="secondary" id="clear-sources">Clear filters</button></form><div id="source-results">${sourceResults()}</div></section><section class="section"><h2>Unresolved discovery leads</h2><p class="caption">A discovery lead is not a confirmed attribution or an acquired corpus.</p><ul class="lead-list">${state.leads.map(l=>`<li>${esc(text(l.label||l.name||l.query||l.id||l))}${l.reason||l.status||l.note?': '+esc(text(l.reason||l.note||l.status)):''}${l.url?' '+link(l.url,'Source lead'):''}</li>`).join('')||'<li>No unresolved leads are listed in these registers.</li>'}</ul></section><div class="downloads"><a href="et-register.json" download>ET register JSON</a><a href="traditions-register.json" download>Traditions register JSON</a><a href="analysis.json" download>Analysis JSON</a><a href="https://github.com/occult-kranti/channels-ET/tree/main/research/expanded-channeling" target="_blank" rel="noopener">Code and research methods</a></div>`;}
let lastTrigger=null;
function inspect(type,id,trigger){let body='',title='Record';if(type==='medium'){const m=medium(id);if(!m)return;title=name(m);const cs=claimsFor(type,id);body=badge(m.role||'human medium')+facts([['Record ID',m.id],['Acquisition status',m.acquisition_status],['Joint practice / affiliation',m.joint_practice||m.affiliation],['Notes',m.notes||m.note]])+`<h3>Publishing accounts</h3><ul class="source-list">${arr(m.accounts).map(a=>`<li>${link(typeof a==='string'?a:a.url,typeof a==='string'?a:(a.label||a.name||a.platform||a.url))}${typeof a==='object'?`<small>Role: ${esc(text(a.role)||'unreported')} · verification: ${esc(text(a.verification)||'unreported')}</small>`:''}</li>`).join('')||'<li>No account URL is asserted in this register.</li>'}</ul><h3>Attributed claims</h3><ul class="inline-list">${cs.map(c=>`<li>${esc(name(entity(c.channellee_id)))} — ${esc(human(c.relation))}; ${esc(text(c.scope))}</li>`).join('')}</ul><h3>Evidence sources</h3>${sourcesBlock([...arr(m.source_ids),...cs.flatMap(c=>arr(c.source_ids))])}`;}else if(type==='entity'){const e=entity(id);if(!e)return;title=name(e);const cs=claimsFor(type,id);body=badge(kind(e))+facts([['Claimed-name record ID',e.id],['Tradition',e.tradition],['Aliases',e.aliases],['Alias status',e.alias_status],['Identity-record scope',e.identity_record_scope||'See alias status and source attribution'],['Notes',e.notes||e.note]])+`<p><strong>This is a claimed source identity.</strong> The register does not establish an independently existing being or equivalence with similarly named records.</p><h3>Linked human mediums / hosts</h3><ul class="inline-list">${cs.map(c=>`<li>${esc(name(medium(c.medium_id)))} — ${esc(human(c.relation))}; ${esc(text(c.scope))}</li>`).join('')}</ul><h3>Evidence sources</h3>${sourcesBlock([...arr(e.source_ids),...cs.flatMap(c=>arr(c.source_ids))])}`;}else if(type==='claim'){const c=state.claims.find(x=>x.id===id);if(!c)return;title=name(medium(c.medium_id))+' → '+name(entity(c.channellee_id));body=facts([['Relationship',human(c.relation)],['Claim scope',c.scope],['Basis of attribution',c.confidence_basis],['Where the attribution appears',c.source_location],['Source summary',c.paraphrase],['Notes',c.notes||c.note],['Claim ID',c.id]])+`<p>The basis concerns whether the source makes this attribution; it is not a confidence estimate of the claimed being’s reality.</p>${sourcesBlock(arr(c.source_ids))}`;}else if(type==='group'){const g=state.groups.find(x=>x.id===id);if(!g)return;title=name(g);body=facts([['Comparison kind',g.kind],['Identity equivalence','Not established'],['Distinct human-medium records',groupMediums(g).length],['Grouping notes',g.notes||g.note]])+`<h3>Source-specific labels</h3><ul class="inline-list">${arr(g.channellee_ids).map(entity).filter(Boolean).map(e=>`<li>${esc(name(e))} · ${esc(e.id)}</li>`).join('')}</ul><h3>Evidence sources</h3>${sourcesBlock(groupClaims(g).flatMap(c=>arr(c.source_ids)))}`;}lastTrigger=trigger||document.activeElement;$('#record-detail').innerHTML=`<h2 id="record-title">${esc(title)}</h2>${body}`;$('#record-dialog').showModal();$('#close-record').focus();}
function exportCsv(filename,headers,rows){const csv=v=>'"'+String(v??'').replace(/^[\t\r\n ]*[=+@-]/,"'$&").replaceAll('"','""')+'"',blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(csv).join(',')).join('\r\n')+'\r\n'],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce(rows.length+' records exported.');}
function exportClaims(rows,file){exportCsv(file,['claim_id','medium_id','human_medium','channellee_id','claimed_label','kind','relation','scope','source_ids'],rows.map(c=>[c.id,c.medium_id,name(medium(c.medium_id)),c.channellee_id,name(entity(c.channellee_id)),kind(entity(c.channellee_id)),c.relation,text(c.scope),arr(c.source_ids).join('; ')]));}
function rerenderResults(id,html,message){$(id).innerHTML=html;announce(message);}
function render(focus=false){const key=location.hash.slice(1).split('?')[0],view=views.includes(key)?key:'register',renders={register,connections,repeated,analysis,coverage,methods};$('#app').innerHTML=renders[view]()+(view==='analysis'?pilotView()+collectedAudioView()+semanticPilotView():view==='coverage'?acquisitionView():'');if(view==='analysis')$('#app .page-head').insertAdjacentHTML('afterend',additionalStudyNav());if(view==='methods'&&extraStudies.reports.length)$('#app').insertAdjacentHTML('beforeend','<div class="downloads">'+reportLinks()+'</div>');$('#app').setAttribute('aria-busy','false');document.title=({register:'Explore identities',connections:'Relationship map',repeated:'Shared-label matrix',analysis:'Text analysis',coverage:'Collection coverage',methods:'Methods & sources'}[view])+' · Channeling Atlas';document.querySelectorAll('.view-nav a').forEach(a=>{if(a.hash==='#'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(focus)$('#main').focus();}
document.addEventListener('submit',e=>{if(e.target.matches('.toolbar'))e.preventDefault();});
document.addEventListener('input',e=>{if(e.target.id==='register-query'){state.query=e.target.value;state.page=1;rerenderResults('#register-results',registerResults(),filteredClaims().length+' relationships match.');}if(e.target.id==='source-query'){state.sourceQuery=e.target.value;state.sourcePage=1;rerenderResults('#source-results',sourceResults(),filteredSources().length+' evidence sources match.');}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='register-kind'||id==='register-tradition'||id==='register-repeated'){state.kind=$('#register-kind').value;state.tradition=$('#register-tradition').value;state.repeated=$('#register-repeated').checked;state.page=1;rerenderResults('#register-results',registerResults(),filteredClaims().length+' relationships match.');}if(id==='graph-group'){state.graphGroup=e.target.value;rerenderResults('#graph-results',graphResults(),'Relationship neighborhood updated.');}if(id==='matrix-mode'){state.groupMode=e.target.value;rerenderResults('#matrix-results',matrixResults(),matrixGroups().length+' comparison groups match.');}if(id==='source-depth'){state.sourceDepth=e.target.value;state.sourcePage=1;rerenderResults('#source-results',sourceResults(),filteredSources().length+' evidence sources match.');}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-inspect]');if(b){inspect(b.dataset.inspect,b.dataset.id,b);return;}const p=e.target.closest('[data-page]');if(p){const step=Number(p.dataset.step);if(p.dataset.page==='register'){state.page+=step;rerenderResults('#register-results',registerResults(),'Relationship page '+state.page);}else{state.sourcePage+=step;rerenderResults('#source-results',sourceResults(),'Evidence page '+state.sourcePage);}const replacement=document.querySelector(`[data-page="${p.dataset.page}"][data-step="${step}"]`);(replacement&&!replacement.disabled?replacement:document.querySelector(`[data-page="${p.dataset.page}"]:not(:disabled)`))?.focus();return;}if(e.target.id==='close-record')$('#record-dialog').close();if(e.target.id==='clear-register'){state.query='';state.kind='all';state.tradition='all';state.repeated=false;state.page=1;render();$('#register-query').focus();announce('All relationship filters cleared.');}if(e.target.id==='clear-sources'){state.sourceQuery='';state.sourceDepth='all';state.sourcePage=1;render();$('#source-query').focus();announce('Source filters cleared.');}if(e.target.id==='export-register')exportClaims(filteredClaims(),'channeling-attributions.csv');if(e.target.id==='export-graph')exportClaims(groupClaims(state.groups.find(g=>g.id===state.graphGroup)),'channeling-neighborhood.csv');if(e.target.id==='export-matrix')exportCsv('channeling-shared-labels.csv',['group_id','label','kind','distinct_medium_records','medium_ids','channellee_ids','identity_equivalence','notes'],matrixGroups().map(g=>[g.id,name(g),g.kind,groupMediums(g).length,groupMediums(g).map(m=>m.id).join('; '),arr(g.channellee_ids).join('; '),'not established',text(g.notes||g.note)]));if(e.target.id==='export-sources')exportCsv('channeling-evidence-sources.csv',['source_id','title','url','access_depth','checked_at','note'],filteredSources().map(s=>[s.id,name(s),s.url,s.access_depth||s.access,s.checked_at,text(s.note)]));if(e.target.id==='retry-load')load();});
document.addEventListener('keydown',e=>{const b=e.target.closest('.graph-node');if(b&&['Enter',' '].includes(e.key)){e.preventDefault();inspect(b.dataset.inspect,b.dataset.id,b);}if(e.key==='Tab'&&$('#record-dialog').open){const all=[...$('#record-dialog').querySelectorAll('a[href],button:not(:disabled),[tabindex="0"]')].filter(el=>el.getClientRects().length),first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#record-dialog').addEventListener('close',()=>{if(lastTrigger?.isConnected)lastTrigger.focus();else $('#main').focus();});window.addEventListener('hashchange',()=>{if(state.registers.length)render(true);});
async function getJson(path){const r=await fetch(path,{cache:'no-cache'});if(!r.ok)throw Error(path+' returned HTTP '+r.status);const d=await r.json();if(d.synthetic_fixture_run===true||d.synthetic===true)throw Error('Synthetic data cannot be used in the released dashboard.');return d;}
async function load(){try{$('#app').setAttribute('aria-busy','true');const rs=await Promise.allSettled([getJson('et-register.json'),getJson('traditions-register.json'),getJson('analysis.json'),getJson('../subscription-audit/data.json')]);for(let i=0;i<2;i++)if(rs[i].status==='rejected')throw rs[i].reason;state.registers=rs.slice(0,2).map(r=>r.value);if(state.registers.some(r=>r.schema_version!==1||!Array.isArray(r.mediums)||!Array.isArray(r.claims)||!Array.isArray(r.channellees)))throw Error('The source-register schema is not supported.');state.analysis=rs[2].status==='fulfilled'?rs[2].value:null;state.analysisError=rs[2].status==='rejected'?rs[2].reason.message:null;state.coverage=rs[3].status==='fulfilled'?rs[3].value:null;state.coverageError=rs[3].status==='rejected'?rs[3].reason.message:null;normalize();await loadExtensions();await loadAdditionalStudies();render();}catch(e){state.registers=[];$('#app').setAttribute('aria-busy','false');$('#app').innerHTML=`<div class="error-panel" role="alert"><h1>Source registers unavailable.</h1><p>The dashboard could not read its source-linked records. No example counts or substitute claims have been displayed.</p><p>${esc(e.message)}</p><button id="retry-load" type="button">Retry loading</button><p>For a local copy, serve the site folder over HTTP. <a href="../#/overview">Return to the Atlas</a>.</p></div>`;}}
load();
